import hashlib,json,re,subprocess
from collections import defaultdict
read_source=lambda path:subprocess.check_output(['git','show','HEAD:'+path],text=True).replace('\r\n','\n')
manifest=json.loads(read_source('Assets/Assets/Resources/YQWorldAssetManifest.json'))
rows=[row for row in manifest['assets'] if isinstance(row,dict) and str(row.get('path','')).lower().endswith('.prefab')]
groups=defaultdict(list)
for row in rows: groups[row['source']].append(row)
issues=[]; counts={'prefabRows':len(rows),'sourceShards':len(groups),'foldedPaths':0,'negativeLocalIds':0,'localIdsBeyondInt32':0}
hash_text=lambda text:hashlib.sha256(text.encode('utf-8')).hexdigest()
for source,wanted in groups.items():
    raw=read_source(source)
    starts=list(re.finditer(r'(?m)^  - assetPath: (.+(?:\n {6}.+)*)\n',raw))
    end=re.search(r'(?m)^  useLazyResourceShards:',raw)
    entries={re.sub(r'\n {6}',' ',m.group(1)):(m,raw[m.start():starts[i+1].start() if i+1<len(starts) else end.start()]) for i,m in enumerate(starts)}
    header=raw[:raw.index('  entries:\n')]+'  entries:\n'
    for row in wanted:
        path=row['path']; m,entry=entries[path]
        refs=list(re.finditer(r'(?m)^    prefab: \{fileID: (-?\d+), guid: ([a-fA-F0-9]{32}), type: 3\}$',entry))
        if len(refs)!=1 or len(re.findall(r'(?m)^    prefab[ \t]*:',entry))!=1: issues.append({'path':path,'problem':'reference count or format','count':len(refs)});continue
        localid=int(refs[0].group(1))
        if localid==0 or not -(2**63)<=localid<2**63: issues.append({'path':path,'problem':'localID bounds','value':str(localid)})
        if refs[0].group(2)=='0'*32: issues.append({'path':path,'problem':'zero GUID'})
        normalized=path.strip().replace('\\','/')
        while '//' in normalized: normalized=normalized.replace('//','/')
        key=hash_text(normalized.lower())
        if row['resource']!='YQWorldAssetLeaves/'+key:issues.append({'path':path,'problem':'resource mismatch'})
        if hash_text(entry)!=row['entrySha256']:issues.append({'path':path,'problem':'entry hash mismatch'})
        leafheader=re.sub(r'(?m)^  m_Name: .+$','  m_Name: YQWorldAsset_'+key,header)
        leaf=leafheader+entry+'  useLazyResourceShards: 0\n  useGranularResourceShards: 0\n  terrainGrassTexture: {fileID: 0}\n'
        if hash_text(leaf)!=row['leafSha256']:issues.append({'path':path,'problem':'leaf hash mismatch'})
        counts['foldedPaths']+=('\n' in m.group(1));counts['negativeLocalIds']+=(localid<0);counts['localIdsBeyondInt32']+=(localid<-(2**31) or localid>=2**31)
print(json.dumps({'counts':counts,'issues':issues[:20],'totalIssues':len(issues)},indent=2))
